; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 1		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

			IF ($ < 32768) && (ntc_rg1_e - ntc_rg1 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
ntc_rg1:
; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 5: Print "start"
			dw kw_printstrvar, str0
			dw kw_printnl

			; main.bas 6: Big
			dw fn_big

			; main.bas 7: a(3) = 7
			dw kw_ltov, 7, arr_a+6

			; main.bas 8: Print "a3 "; a(3); " big at "; Hex$(Where()); " end "; Hex$(Memory.ProgramEnd())
			dw kw_printstrvar, str1
			dw kw_printint, arr_a+6
			dw fn_where, var_where_where
			dw kw_vtov, var_where_where, tmp0
			dw kw_strhex, stmp0, tmp0
			dw kw_printstrvar, str2
			dw kw_printstrvar, stmp0
			dw fn_memory_programend, var_memory_programend_programend
			dw kw_vtov, var_memory_programend_programend, tmp0
			dw kw_strhex, stmp0, tmp0
			dw kw_printstrvar, str3
			dw kw_printstrvar, stmp0
			dw kw_printnl
			dw kw_stop

ntc_rg1_e:
			IF ($ < 32768) && (ntc_rg2_e - ntc_rg2 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
ntc_rg2:
; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_big:		; sub big (asm keyword), main.bas line 10
            jp fn_big_bg_e		; main.bas 11
            ds 15600		; main.bas 12
fn_big_bg_e:		; main.bas 13
			ret			; end of #asm

fn_where:		; function where (asm keyword), main.bas line 17
            pop hl		; main.bas 18
            ld de, fn_big		; main.bas 19
            ld (hl), e		; main.bas 20
            inc hl		; main.bas 21
            ld (hl), d		; main.bas 22
			ret			; end of #asm

fn_memory_programend:		; function programend (asm keyword), Memory.cls line 167
            pop hl		; Memory.cls 168
            ld (mem_res), hl		; Memory.cls 169
            ld hl, mem_progend		; Memory.cls 170
            jp mem_go		; Memory.cls 171
			ret			; end of #asm


ntc_rg2_e:
			IF ($ < 32768) && (ntc_rg3_e - ntc_rg3 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
